import React, { useState, useEffect } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import ProductCard from '../components/ProductCard';
import ProductModal from '../components/ProductModal';

const Home = () => {
    const { user } = useAuth();
    const [searchParams] = useSearchParams();
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [category, setCategory] = useState('todos');
    const [selectedProduct, setSelectedProduct] = useState(null);
    const [modalOpen, setModalOpen] = useState(false);
    const [stats, setStats] = useState(null);

    useEffect(() => {
        fetchStats();
        fetchProducts();
    }, [category, searchParams]);

    const fetchStats = async () => {
        try {
            const response = await api.get('/stats');
            setStats(response.data);
        } catch (error) {
            console.error('Erro ao buscar estatísticas:', error);
        }
    };

    const fetchProducts = async () => {
        setLoading(true);
        try {
            const search = searchParams.get('search') || '';
            const response = await api.get('/products', {
                params: { category: category !== 'todos' ? category : undefined, search, limit: 12 }
            });
            setProducts(response.data.products);
        } catch (error) {
            console.error('Erro ao buscar produtos:', error);
        } finally {
            setLoading(false);
        }
    };

    const openModal = (product) => {
        setSelectedProduct(product);
        setModalOpen(true);
    };

    const closeModal = () => {
        setModalOpen(false);
        setSelectedProduct(null);
    };

    // Listener para abrir modal a partir do dashboard do vendedor
    useEffect(() => {
        const handleOpenModal = (event) => {
            if (event.detail) {
                openModal(event.detail);
            }
        };
        
        window.addEventListener('openProductModal', handleOpenModal);
        
        return () => {
            window.removeEventListener('openProductModal', handleOpenModal);
        };
    }, []);

    const categories = [
        { id: 'todos', name: 'Todos', icon: '📦' },
        { id: 'telemovel', name: 'Telemóveis', icon: '📱' },
        { id: 'laptop', name: 'Laptops', icon: '💻' },
        { id: 'console', name: 'Consoles', icon: '🎮' },
        { id: 'tablet', name: 'Tablets', icon: '📟' }
    ];

    return (
        <div>
            {/* Hero Section */}
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-2xl p-8 mb-8 text-center dark:from-gray-800 dark:to-gray-900">
                <h1 className="text-3xl md:text-4xl font-bold mb-4">InterConectados</h1>
                <p className="text-lg md:text-xl mb-6 opacity-90">Conectando pessoas através da tecnologia</p>
                {!user && (
                    <div className="flex justify-center gap-4">
                        <Link to="/register" className="bg-white text-blue-600 px-6 py-3 rounded-lg font-semibold hover:bg-gray-100 transition dark:bg-gray-800 dark:text-white dark:hover:bg-gray-700">
                            Começar a Comprar
                        </Link>
                        <Link to="/register" className="border-2 border-white text-white px-6 py-3 rounded-lg font-semibold hover:bg-white hover:text-blue-600 transition dark:border-gray-600 dark:hover:bg-gray-800">
                            Anunciar Grátis
                        </Link>
                    </div>
                )}
            </div>

            {/* Estatísticas */}
            {stats && (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                    <div className="bg-white dark:bg-gray-800 rounded-lg p-4 text-center shadow">
                        <div className="text-2xl font-bold text-blue-600 dark:text-blue-400 mb-1">{stats.totalProducts}</div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">Produtos</div>
                    </div>
                    <div className="bg-white dark:bg-gray-800 rounded-lg p-4 text-center shadow">
                        <div className="text-2xl font-bold text-blue-600 dark:text-blue-400 mb-1">{stats.totalUsers}</div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">Usuários</div>
                    </div>
                    <div className="bg-white dark:bg-gray-800 rounded-lg p-4 text-center shadow">
                        <div className="text-2xl font-bold text-blue-600 dark:text-blue-400 mb-1">{stats.totalSellers}</div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">Vendedores</div>
                    </div>
                    <div className="bg-white dark:bg-gray-800 rounded-lg p-4 text-center shadow">
                        <div className="text-2xl font-bold text-blue-600 dark:text-blue-400 mb-1">100%</div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">Seguro</div>
                    </div>
                </div>
            )}

            {/* Categorias */}
            <div className="flex flex-wrap gap-2 mb-6">
                {categories.map(cat => (
                    <button
                        key={cat.id}
                        onClick={() => setCategory(cat.id)}
                        className={`px-4 py-2 rounded-full flex items-center gap-2 transition ${
                            category === cat.id
                                ? 'bg-blue-600 text-white dark:bg-blue-500'
                                : 'bg-white text-gray-700 hover:bg-gray-100 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700'
                        }`}
                    >
                        <span>{cat.icon}</span>
                        <span>{cat.name}</span>
                    </button>
                ))}
            </div>

            {/* Produtos */}
            <h2 className="text-2xl font-bold text-gray-800 dark:text-gray-200 mb-4">Últimos Anúncios</h2>
            {loading ? (
                <div className="flex justify-center py-12">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 dark:border-blue-400"></div>
                </div>
            ) : products.length === 0 ? (
                <div className="bg-white dark:bg-gray-800 rounded-xl p-12 text-center shadow">
                    <p className="text-gray-500 dark:text-gray-400">Nenhum produto encontrado.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {products.map(product => (
                        <ProductCard 
                            key={product.id} 
                            product={product} 
                            onClick={() => openModal(product)}
                        />
                    ))}
                </div>
            )}

            {/* Modal de detalhes do produto */}
            <ProductModal 
                product={selectedProduct}
                isOpen={modalOpen}
                onClose={closeModal}
            />
        </div>
    );
};

export default Home;
